function action(type,id){
  if(type==='map'){stop();mapOpen=true;render(false);}
  if(type==='close-map'){mapOpen=false;render(false);document.querySelector('[data-action=map]')?.focus();}
  if(type==='choose-first'){returnSection=state.section;go(0);}
  if(type==='back'){if(state.section===6&&cueStep===1){stop();cueStep=0;render();}else go(state.section-1);}
  if(type==='cue-next'){cueStep=1;render();}
  if(type==='next'){if(!state.context){notice='Choose Pool split or Stage rehearsal to continue.';render(false);return;}notice='';if(state.section===6&&cueStep===0){if(state.miniRecords?.originalCue){cueStep=1;render();}else{miniFeedback.originalCue={title:'Check the original plan first',html:'<p>Choose early, on time, or late, then select Check the timing.</p>',error:true};render(false);document.querySelector('#mini-feedback-originalCue')?.focus({preventScroll:true});}return;}if(state.section===0&&returnSection!==null){const destination=returnSection;returnSection=null;go(destination);}else go(state.section+1);}
  if(type==='hint')hint(id);
  if(type==='support')supported(id);
  if(type==='other-fix')changeRoute(plan().route==='pace'?'start':'pace');
  if(type==='run'){if(raf){stop();render(false);}else run();}
  if(type==='replay'){stop();cueTime=0;updateCue();run();}
  if(type==='practice'){showPractice=!showPractice;render(false);}
  if(type==='download'){const data={...normalizeStateEvidence(state),completed:complete(state),evidence:Object.fromEntries(CORE.map(id=>[id,evidence(state.records[id],state.supports[id]||[])])),notice:'Your Hit Your Mark work from this browser: first tries, latest answers, help used, and explanations.'};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='hit-your-mark-my-work.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
  if(type==='restart'){stop();mapOpen=false;restartGate.request();render(false);}
  if(type==='cancel-restart'){restartGate.cancel();render(false);document.querySelector('[data-action="restart"]')?.focus({preventScroll:true});}
  if(type==='confirm-restart')restartGate.confirm(()=>{stop();state=initialState();feedback={};miniFeedback={};openExplainers.clear();hintText={};drawn={};restored=false;cueTime=0;workStep=0;showPractice=false;returnSection=null;notice='Your lesson was restarted.';try{localStorage.removeItem(KEY);}catch{storageOK=false;}save();render();});
}
function rememberPlan(){const p=plan(),key=`${p.route}:${p.index}`;if(!state.cueExplored.includes(key))state.cueExplored.push(key);}
function changeRoute(route){stop();delete feedback.cue;draft('cue').route=route;draft('cue').index=route==='pace'?sc().cue.paceIndex:sc().cue.startIndex;draft('cue').equation='';cueTime=0;rememberPlan();save();render(false);}
function updateCue(){const p=plan();document.querySelector('#cue-scene').innerHTML=compactScene(p.b,p.speed,cueTime);document.querySelector('#cue-graph').innerHTML=cueGraph(p);document.querySelector('#cue-time-label').textContent=fmt(cueTime)+' s';const el=document.querySelector('#cue-time');el.value=cueTime;el.setAttribute('aria-valuetext',fmt(cueTime)+' seconds');const btn=document.querySelector('[data-action=run]');if(btn)btn.textContent=raf?'Pause rehearsal':'Run rehearsal';}
function run(){const p=plan();if(matchMedia('(prefers-reduced-motion: reduce)').matches){cueTime=Math.min(sc().cue.goal,p.seconds);updateCue();notice=`Reduced motion is on, so the scene jumps to ${sc().cue.goal} seconds (or arrival).`+' Use the time slider to look at any moment.';render(false);return;}if(cueTime>=p.seconds)cueTime=0;lastAnimation=0;const tick=t=>{if(!lastAnimation)lastAnimation=t;cueTime=Math.min(p.seconds,cueTime+(t-lastAnimation)/1000);lastAnimation=t;if(cueTime<p.seconds)raf=requestAnimationFrame(tick);else raf=0;updateCue();};raf=requestAnimationFrame(tick);updateCue();}
function requiredChoice(id,key,label){const v=draft(id)[key];if(!v)throw new InputError(label);return v;}
