  if(id==='independent'||id.startsWith('practice')){const spec=id==='independent'?{m:2/3,b:-2}:practice.find(p=>p.id===id),d=draft(id),p=graphResponse(id);const direction=requiredChoice(id,'direction','Choose whether the line rises, falls, or stays level.');const raw=String(d.xIntercept||'').trim().toLowerCase();const xi=/^(none|no|no x[- ]?intercept)$/.test(raw)?null:number(d.xIntercept);const r=checkGraph(p,spec.m,spec.b,{xIntercept:xi,direction});drawn[id]=p;record(id,{...p,direction,xIntercept:xi,explanation:d.explanation||''},{...r,explanationAutomaticallyGraded:false});let parts=[r.first?`✓ The y-intercept is (0, ${spec.b}).`:`Start where x = 0. The y-intercept is (0, ${spec.b}).`,r.distinct?(r.second?'✓ Your different point satisfies the equation.':`Your second point must satisfy ${equationText(spec.m,spec.b)}. Substitute its x-value to check its y-value.`):'Use a different x-value for your second point; these graphs are nonvertical.',r.direction?'✓ Direction agrees with the slope.':`The slope is ${spec.m>0?'positive, so the line rises':spec.m<0?'negative, so the line falls':'zero, so the line stays level'}.`,r.xIntercept?`✓ ${spec.m===0?'This line has no x-intercept.':`The x-intercept is (${fmt(-spec.b/spec.m)}, 0).`}`:`${spec.m===0?'y stays 3, so the line never reaches y = 0. Enter none.':`Set y = 0: the x-intercept is (${fmt(-spec.b/spec.m)}, 0).`}`];setFeedback(id,r.correct?'✓ Your construction fits':'Revise using the equation',parts.map(x=>`<p>${x}</p>`).join('')+(id==='independent'?`<div class="comparison"><strong>${String(d.explanation||'').trim()?'Compare your explanation':'Example explanation'}:</strong> The y-intercept is (0, −2). From there, a rise of 2 for a run of 3 gives slope 2/3. Equivalent steps and equivalent points work too.</div>`:''),r.correct);}
  if(id==='transfer'){const d=draft(id),start=number(d.start),a=number(d.arrival),rate=requiredChoice(id,'rate','Choose a meaning for the rate.'),domain=requiredChoice(id,'domain','Choose a useful domain graph.');const r=checkTransfer({start,arrival:a,rate,domain},sc()),pool=isPool();record(id,{...d,start,arrival:a},{...r,reflectionAutomaticallyGraded:false});setFeedback(id,r.correct?'✓ The fresh model fits its context':'Check each part of the new model',pool?`<p>${r.start?'✓':'↻'} Starting distance: 4 meters from the wall. The y-intercept is (0, 4).</p><p>${r.rate?'✓':'↻'} The rate 4/5 is an increase of 4 meters from the wall for every 5 seconds.</p><p>${r.arrival?'✓':'↻'} Far wall: 10 seconds. Solve 12 = 0.8x + 4, so x = 10 and the point is (10, 12).</p><p>${r.domain?'✓':'↻'} Use the finite segment 0 ≤ x ≤ 10. This swim ends at the far wall.</p><div class="comparison"><strong>${String(d.explanation||'').trim()?'Compare your reflection':'Example explanation'}:</strong> After the far wall, continuing the line would put the swimmer more than 12 meters from the start wall, outside the pool. This model ends at y = 12.</div>`:`<p>${r.start?'✓':'↻'} Starting distance: 5 meters. The y-intercept is (0, 5).</p><p>${r.rate?'✓':'↻'} The rate is a decrease of 1 meter in the distance remaining for every 2 seconds.</p><p>${r.arrival?'✓':'↻'} Arrival: 10 seconds. The x-intercept is (10, 0).</p><p>${r.domain?'✓':'↻'} Use the finite segment 0 ≤ x ≤ 10. This approach ends at the ${context().target}.</p><div class="comparison"><strong>${String(d.explanation||'').trim()?'Compare your reflection':'Example explanation'}:</strong> After arrival, continuing the line would predict negative meters remaining. This particular approach model ends at y = 0; it is not a model of what happens afterward.</div>`,r.correct);}
