const hintMessages={predict:['Look for the distance at zero seconds, then compare it with the distance at four seconds.','The scene starts at 6 meters remaining and shows 3 meters remaining after four seconds. How much closer is that?'],roles:['Ask what each quantity measures. A starting value is read when x = 0.','6 is initial meters remaining; −3/4 is change per second; x is elapsed seconds; y is meters remaining.'],guided:['In −3/4, the denominator tells the horizontal change; the numerator tells the vertical change.','Start at (0, 9). Move right 4 and down 3 to (4, 6). Continue that pattern until zero meters remain.'],diagnose:['The point (0, 6) already matches the initial value. Check which change belongs to the numerator.','Keep the intercept. Use horizontal 4 and vertical −3, so the slope is −3/4.'],cue:['Arrival time = starting distance ÷ approach speed. Is your current arrival early, late, or exactly six?','One fix keeps 6 meters and uses 1 m/s. Another keeps 0.75 m/s and uses a 4.5-meter start. Match the equation to whichever route you choose.'],independent:['The constant term gives the y-coordinate when x = 0. A positive slope rises as x increases.','Use (0, −2), then rise 2 and run 3 to (3, 0). Both points satisfy y = (2/3)x − 2. The x-intercept is 3.'],transfer:['Read the starting value at x = 0. The arrival occurs when meters remaining reach zero.','Five meters at half a meter per second takes 10 seconds. A finite segment ends at (10, 0).']};
const poolHints={predict:['Look for the distance from the wall at zero seconds, then compare it with the distance at four seconds.','The swimmer starts 3 meters from the wall and is 9 meters out after four seconds. How much farther is that?'],roles:['Ask what each quantity measures. A starting value is read when x = 0.','3 is the initial meters from the start wall; 3/2 is change per second; x is elapsed seconds; y is meters from the start wall.'],guided:['In 3/2, the denominator tells the horizontal change; the numerator tells the vertical change.','Start at (0, 0). Move right 2 and up 3 to (2, 3). Continue that pattern until y reaches 12, the far wall.'],diagnose:['The point (0, 3) already matches the glide. Check which change belongs to the numerator.','Keep the intercept. Use horizontal 2 and vertical +3, so the slope is 3/2.'],cue:['Time to the far wall = (12 − glide distance) ÷ speed. Is your current arrival early, late, or exactly five?','One fix keeps the 3-meter glide and swims 1.8 m/s. Another keeps 1.5 m/s and glides 4.5 meters. Match the equation to whichever route you choose.'],transfer:['Read the starting value at x = 0. The swim ends when y reaches 12, the far wall.','Eight meters to go at 0.8 m/s takes 10 seconds. A finite segment ends at (10, 12).']};
function hint(id){const used=state.supports[id]||[],n=used.includes('hint-1')?1:0;state=addSupport(state,id,'hint-'+(n+1));let texts=(isPool()&&poolHints[id])||hintMessages[id];if(id.startsWith('practice')){const p=practice.find(x=>x.id===id);texts=[`Begin at (0, ${p.b}). Read the sign of the slope to choose the direction.`,`A valid second point is (1, ${p.m+p.b}). ${p.m===0?'This horizontal line has no x-intercept.':`The x-intercept is ${fmt(-p.b/p.m)}.`}`];}hintText[id]=texts[n];save();render(false);}
function practiceComparison(id){const p=practice.find(x=>x.id===id);return `Start at (0, ${p.b}). A different point is (1, ${p.m+p.b}). The line ${p.m>0?'rises':p.m<0?'falls':'stays level'}. ${p.m===0?'There is no x-intercept.':`The x-intercept is (${fmt(-p.b/p.m)}, 0).`}`;}
function supported(id){state=addSupport(state,id,'worked-comparison');const response={...(state.records[id]?.latest.response||draft(id)),supportRoute:'Continue with support',currentDraft:{...draft(id)},originalLatest:state.records[id]?.latest.response||null};record(id,response,{correct:null,ungraded:true,workedComparison:true},{supported:true});const model=isPool()?{predict:'At zero seconds the swimmer is 3 meters from the wall. After four seconds, 9 meters. The distance grew by 6 meters. The graph next will show the far wall at six seconds.',roles:'3: initial meters from the start wall. 3/2: change in meters from the wall per second. x: elapsed seconds. y: meters from the start wall.',guided:'Start (0, 0). Right 2, up 3 reaches (2, 3). The useful segment ends at (8, 12), so the far wall comes at 8 seconds.',diagnose:'Exchange the changes. Keep (0, 3), then move right 2 / up 3. The correct graph reaches (6, 12).',cue:'A 3-meter glide with a 1.8 m/s swim reaches the far wall at five seconds. A 4.5-meter glide at 1.5 m/s also works. Select the equation for your current route to test again.',independent:'Start (0, −2); rise 2 and run 3 to (3, 0). The line rises and its x-intercept is 3.',transfer:'Start 4 meters from the wall; increase by 4 meters every 5 seconds; reach the far wall (12 m) at 10 seconds. Use a segment from (0, 4) to (10, 12).'}:{predict:'At zero seconds 6 meters remain. After four seconds, 3 meters remain. The distance decreased by 3 meters. The graph next will show arrival at eight seconds.',roles:'6: initial meters remaining. −3/4: change in meters remaining per second. x: elapsed seconds. y: meters remaining.',guided:'Start (0, 9). Right 4, down 3 reaches (4, 6). The useful segment ends at (12, 0), so arrival is 12 seconds.',diagnose:'Exchange the changes. Keep (0, 6), then move right 4 / down 3. The correct graph reaches (8, 0).',cue:'A 6-meter start with 1 m/s approach reaches the target at six seconds. A 4.5-meter start with 0.75 m/s also works. Select the equation for your current route to test again.',independent:'Start (0, −2); rise 2 and run 3 to (3, 0). The line rises and its x-intercept is 3.',transfer:'Start 5 meters away; decrease remaining distance by 1 meter every 2 seconds; arrive at 10 seconds. Use a segment from (0, 5) to (10, 0).'};setFeedback(id,'Here’s a worked example',`<p>${model[id]||hintMessages[id]?.[1]||(id.startsWith('practice')?practiceComparison(id):'Use the intercept and slope to compare your construction with the model.')}</p><p>Compare it with your work. Your earlier answers are still saved, and this activity now counts as done.</p>`,false);}
